solution.solution.cpp:
#include <algorithm>
#include <cmath>
#include <string>
#include <vector>

struct Vector2 { float x, y; };
struct Rectangle { float x, y, width, height; };

struct Level { std::vector<std::string> rows; };
struct Input { float x{ 0 }; bool jumpPressed{ false }, jumpReleased{ false }; };
struct Player
{
    Rectangle box{ 0, 0, 24, 30 };
    Vector2 vel{ 0, 0 };
    bool onGround{ false };
    float coyote{ 0 }, buffer{ 0 };
};

namespace
{
    constexpr float Tile{ 32 };

    float approach(float v, float target, float maxDelta)
    {
        if (v < target) return std::min(v + maxDelta, target);
        return std::max(v - maxDelta, target);
    }

    int first(float v) { return static_cast<int>(std::floor(v / Tile)); }
    int last(float v) { return static_cast<int>(std::ceil(v / Tile)) - 1; }
}

bool solidAt(const Level& level, int tx, int ty)
{
    if (ty >= static_cast<int>(level.rows.size())) return false;
    if (ty < 0 || tx < 0) return true;
    const std::string& row{ level.rows[static_cast<std::size_t>(ty)] };
    if (tx >= static_cast<int>(row.size())) return true;
    return row[static_cast<std::size_t>(tx)] == '#';
}

void step(Player& p, const Level& level, const Input& in, float dt)
{
    const float rate{ p.onGround ? (in.x != 0 ? 1600.0f : 2000.0f) : 900.0f };
    p.vel.x = approach(p.vel.x, in.x * 200.0f, rate * dt);

    p.coyote = p.onGround ? 0.1f : p.coyote - dt;
    p.buffer = in.jumpPressed ? 0.1f : p.buffer - dt;
    if (p.coyote > 0 && p.buffer > 0)
    {
        p.vel.y = -480.0f;
        p.coyote = p.buffer = 0;
        p.onGround = false;
    }

    if (in.jumpReleased && p.vel.y < 0) p.vel.y *= 0.5f;
    p.vel.y = std::min(p.vel.y + (p.vel.y > 0 ? 2160.0f : 1200.0f) * dt, 600.0f);

    Rectangle& b{ p.box };
    b.x += p.vel.x * dt;
    float stop{ b.x };
    bool blocked{ false };
    for (int ty{ first(b.y) }; ty <= last(b.y + b.height); ++ty)
        for (int tx{ first(b.x) }; tx <= last(b.x + b.width); ++tx)
        {
            if (!solidAt(level, tx, ty)) continue;
            if (p.vel.x > 0) { stop = std::min(stop, tx * Tile - b.width); blocked = true; }
            else if (p.vel.x < 0) { stop = std::max(stop, (tx + 1) * Tile); blocked = true; }
        }
    if (blocked) { b.x = stop; p.vel.x = 0; }

    b.y += p.vel.y * dt;
    stop = b.y;
    bool ground{ false }, ceiling{ false };
    for (int ty{ first(b.y) }; ty <= last(b.y + b.height); ++ty)
        for (int tx{ first(b.x) }; tx <= last(b.x + b.width); ++tx)
        {
            if (!solidAt(level, tx, ty)) continue;
            if (p.vel.y > 0) { stop = std::min(stop, ty * Tile - b.height); ground = true; }
            else if (p.vel.y < 0) { stop = std::max(stop, (ty + 1) * Tile); ceiling = true; }
        }
    if (ground || ceiling) { b.y = stop; p.vel.y = 0; }
    p.onGround = ground;
}

unitTests:
const float dt = 1.0f / 60;
const Level room{ { "........", "........", "........", "...#....", "########" } };
const Level flat{ { "........", "........", "........", "........", "########" } };
const Level air{ { "........", "........", "........", "........", "........", "........" } };
const Level low{ { "########", "........", "........", "########" } };
Player standing(float x, float y) { Player p; p.box.x = x; p.box.y = y; p.onGround = true; return p; }
TEST("solid tiles and the edges of the map") { CHECK(solidAt(room, 3, 3)); CHECK(!solidAt(room, 2, 3)); CHECK(solidAt(room, -1, 0)); CHECK(solidAt(room, 8, 0)); CHECK(solidAt(room, 0, -1)); CHECK(!solidAt(room, 0, 5)); }
TEST("falling and landing") { Player p; p.box.x = 40; p.box.y = 60; for (int i = 0; i < 120; ++i) step(p, room, {}, dt); CHECK_NEAR(p.box.y, 98.0, 1e-3); CHECK(p.onGround); CHECK_NEAR(p.vel.y, 0.0, 1e-6); }
TEST("running speeds up and slows down") {
    Player p = standing(40, 98); for (int i = 0; i < 40; ++i) step(p, flat, { 1 }, dt);
    CHECK_NEAR(p.vel.x, 200.0, 1e-3); CHECK_NEAR(p.box.x, 162.444, 0.05); CHECK(p.onGround);
    for (int i = 0; i < 6; ++i) step(p, flat, {}, dt); CHECK_NEAR(p.vel.x, 0.0, 1e-3);
}
TEST("a wall stops the player") { Player p = standing(40, 98); for (int i = 0; i < 60; ++i) step(p, room, { 1 }, dt); CHECK_NEAR(p.box.x, 72.0, 1e-3); CHECK(p.onGround); }
TEST("the jump's height") {
    Player p = standing(40, 98); step(p, room, { 0, true }, dt); CHECK(!p.onGround); CHECK_NEAR(p.vel.y, -460.0, 1e-3);
    float top = p.box.y; for (int i = 0; i < 60; ++i) { step(p, room, {}, dt); top = std::min(top, p.box.y); }
    CHECK_NEAR(top, 6.0, 0.5); for (int i = 0; i < 60; ++i) step(p, room, {}, dt); CHECK(p.onGround); CHECK_NEAR(p.box.y, 98.0, 1e-3);
}
TEST("cutting the jump short") { Player p = standing(40, 98); step(p, room, { 0, true }, dt); step(p, room, { 0, false, true }, dt); CHECK_NEAR(p.vel.y, -210.0, 1e-3); }
TEST("coyote time") {
    Player p = standing(100, 20); step(p, air, {}, dt); CHECK(!p.onGround); step(p, air, {}, dt); step(p, air, { 0, true }, dt); CHECK(p.vel.y < 0);
    Player q = standing(100, 20); for (int i = 0; i < 7; ++i) step(q, air, {}, dt); step(q, air, { 0, true }, dt); CHECK(q.vel.y > 0);
}
TEST("a buffered jump") {
    Player p; p.box.x = 40; p.box.y = 96; p.vel.y = 120;
    step(p, room, { 0, true }, dt); CHECK(p.onGround); CHECK_NEAR(p.box.y, 98.0, 1e-3);
    step(p, room, {}, dt); CHECK(p.vel.y < 0); CHECK(!p.onGround);
}
TEST("bumping the ceiling") {
    Player p = standing(40, 66); step(p, low, { 0, true }, dt);
    float top = p.box.y; for (int i = 0; i < 30; ++i) { step(p, low, {}, dt); top = std::min(top, p.box.y); }
    CHECK_NEAR(top, 32.0, 1e-3); for (int i = 0; i < 120; ++i) step(p, low, {}, dt); CHECK_NEAR(p.box.y, 66.0, 1e-3);
}
TEST("the map's walls and falling out") {
    Player p; p.box.x = 2; p.box.y = 20; for (int i = 0; i < 10; ++i) step(p, air, { -1 }, dt); CHECK_NEAR(p.box.x, 0.0, 1e-4);
    for (int i = 0; i < 120; ++i) step(p, air, {}, dt); CHECK_NEAR(p.vel.y, 600.0, 1e-3); CHECK(p.box.y > 192);
}

